// Problem Solver's Pareto analysis as the book uses it: 80/20 is a guide and not a rule, the
// last stretch of finishing can cost out of proportion, and the reflection ranges over work,
// friendships and stress. It keeps the figures and the ranking, takes the Explore step, and
// ends with a reflection in place of a chosen option (Act takes over from there).
export const rbPareto = paretoTool({
  id: 'rb_pareto',
  name: 'The Pareto Principle',
  kind: 'diagnostic',
  step: 'explore',
  when: 'A few activities may account for a large part of your results or strain.',
  failureModes: [
    'Forcing every distribution to equal eighty/twenty',
    'Cutting essential finishing work',
    'Counting easy metrics instead of relevant outcomes'
  ],
  steps: [
    step('target', 'Set the target', 'Say what you are weighing up: results at work, the friendships that matter, or where stress comes from, and over what period.'),
    step('items', 'List the contributions', 'List the activities or sources at the same level, at least three.'),
    step('data', 'Add the figures', 'Give each one a figure, however rough; the chart ranks them. Eighty/twenty is a guide, so expect the split to differ.'),
    step('reflect', 'Read it for the situation', 'Which few create most of the value or strain, and which finishing work is genuinely essential even though it is costly?')
  ],
  exercise: 'Review recent activities, protect one high-value contribution and decide where adequate is good enough.',
  reflection: 'What the ranking shows about where value or strain comes from, and which finishing work is essential'
});

